const inp = $input.first().json;
const REQUIRED = ['userId','sessionId','remoteJid','instance'];
const missing  = REQUIRED.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { success: false, error: 'MISSING_FIELDS', details: missing, original: inp } }];
}
return [{ json: { success: true, ...inp } }];

// Carga datos del KB solo si procedure_key ya existe en el contexto
// (fue seleccionado en un mensaje anterior).
// Si no existe, devuelve __skip__ para que db_manager retorne vacío gracefully.
// Se lee POR NOMBRE: ahora hay llamadas de catálogo encadenadas antes,
// así que $input ya no trae el payload original.
const ctx  = $('🔍 Validar Input SAGE').first().json.sessionContext || {};
const sage = ctx.sage || {};
const key  = sage.procedure_key || null;

if (!key) {
  // No hay procedimiento seleccionado aún — skip DB call
  return [{ json: { operation: '__skip__', params: {} } }];
}
return [{ json: { operation: 'getProcedure', params: { procedureKey: key } } }];

// ============================================================
// SAGE v2.1.0 — Especialista en Cotizaciones Médicas
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
//
// CAMBIOS v2.0.8:
//   - FIX CRÍTICO: handoff_received usa txt (mensaje actual) PRIMERO,
//     pendingMessage solo como fallback → elimina el bug "Implante Dental ✅"
//     cuando el usuario ya estaba en un flujo anterior
//   - Aliases enriquecidos: 'rinplas' para rinoplastía (typo tolerante)
//     'liposuc' para liposucion, prefijos cortos para todos los procedimientos
//   - matching bidireccional: txtN includes alias OR alias includes txtN-word
//   - Escape en questioning: usuario puede escribir 'comparar'/'atlas' para salir
//   - Escape en cualquier estado: saludo resetea a bienvenida normal
// ============================================================

const inp             = $('🔍 Validar Input SAGE').first().json;
// Se lee POR NOMBRE de nodo, no por $input: ahora hay varias llamadas al
// db_manager encadenadas antes del motor, y $input apuntaría a la última.
const procedureResult = $('🗄️ DB — Cargar Procedimiento').first().json;

// ══════════════════════════════════════════════════════════════
// CAPA DE ADAPTACIÓN DE CATÁLOGOS  (v2.1.1)
// ──────────────────────────────────────────────────────────────
// Punto único donde SAGE obtiene datos que en PRODUCCIÓN son
// propiedad de Pangi (se administran desde admin.pangi.com).
//
// Hoy: devuelven los literales del MVP → comportamiento idéntico.
// Producción: un nodo previo inyecta el catálogo real del API de
// Pangi y estas funciones lo devuelven. Los sitios de uso NO
// cambian. El literal queda como fallback si el API no responde.
//
// ⚠️ Estas listas NO deben editarse a mano una vez integrado el
//    catálogo de Pangi: la fuente de verdad es el admin.
// ══════════════════════════════════════════════════════════════

// Procedimientos por especialidad (nombres i18n + key de la KB).
// PRODUCCIÓN: catálogo de tratamientos activos de Pangi.
function getProcedures() {
  // 1) Intersección KB ∩ catálogo activo de Pangi, ya ordenada por
  //    display_order (el orden ES lo que el paciente ve numerado).
  try {
    const r = $('🗄️ DB — Cargar Procedimientos').first().json;
    if (r && r.success === true && Array.isArray(r.data) && r.data.length > 0) {
      const out = { dental: [], plastic_surgery: [] };
      for (const row of r.data) {
        if (!row || !out[row.specialty]) continue;
        out[row.specialty].push({
          name:   row.name_es || row.procedure_name,
          nameEn: row.name_en || row.name_es || row.procedure_name,
          namePt: row.name_pt || row.name_es || row.procedure_name,
          key:    row.procedure_key,
          // Nombres EXACTOS de Pangi: viajan a `category` y `procedures`
          // en post-treatment-concern, que compara cadenas literales.
          pangiSpecialty: row.pangi_specialty_name || null,
          pangiProcedure: row.pangi_procedure_name || null,
          maxProcedures:  row.allow_number_of_procedure || 1,
          photoGuide:     row.doc_es || row.doc_en || null
        });
      }
      if (out.dental.length > 0 || out.plastic_surgery.length > 0) return out;
    }
  } catch (e) { /* nodo ausente o sin ejecutar → fallback */ }

  // 2) Inyección directa por input (compatibilidad).
  const c = inp.catalogProcedures;
  if (c && typeof c === 'object' && Array.isArray(c.dental) && Array.isArray(c.plastic_surgery)) {
    return c;
  }
  return {
  dental: [
    { name: 'Extracción Simple',              nameEn: 'Simple Tooth Extraction',       namePt: 'Extração Simples',              key: 'extraccion_simple'       },
    { name: 'Extracción Muela del Juicio',     nameEn: 'Wisdom Tooth Extraction',       namePt: 'Extração do Siso',              key: 'extraccion_muela_juicio' },
    { name: 'Implante Dental',                nameEn: 'Dental Implant',                namePt: 'Implante Dentário',             key: 'implante_dental'         },
    { name: 'Prótesis Dental Completa',       nameEn: 'Complete Dentures',             namePt: 'Prótese Dentária Completa',     key: 'protesis_completa'       },
    { name: 'Carillas / Veneers',             nameEn: 'Porcelain Veneers',             namePt: 'Facetas Dentárias',             key: 'carillas_veneers'        },
    { name: 'Ortodoncia Brackets',            nameEn: 'Traditional Braces',            namePt: 'Aparelho Dentário Fixo',        key: 'ortodoncia_brackets'     },
    { name: 'Ortodoncia Invisible',           nameEn: 'Clear Aligners (Invisalign)',   namePt: 'Alinhadores Invisíveis',        key: 'ortodoncia_invisible'    },
    { name: 'Endodoncia (Conducto)',          nameEn: 'Root Canal Treatment',          namePt: 'Tratamento de Canal',           key: 'endodoncia'              },
    { name: 'Corona Dental',                  nameEn: 'Dental Crown',                  namePt: 'Coroa Dentária',                key: 'corona_dental'           },
    { name: 'Limpieza Profunda (Periodoncia)', nameEn: 'Deep Cleaning (Periodontics)',  namePt: 'Limpeza Profunda (Periodontia)', key: 'limpieza_profunda'      },
    { name: 'Blanqueamiento Dental',          nameEn: 'Teeth Whitening',               namePt: 'Clareamento Dental',            key: 'blanqueamiento'          },
    { name: 'Puente Dental',                  nameEn: 'Dental Bridge',                 namePt: 'Ponte Dentária',                key: 'puente_dental'           }
  ],
  plastic_surgery: [
    { name: 'Rinoplastia',                    nameEn: 'Rhinoplasty (Nose Job)',         namePt: 'Rinoplastia',                   key: 'rinoplastia'             },
    { name: 'Abdominoplastia',                nameEn: 'Tummy Tuck',                    namePt: 'Abdominoplastia',               key: 'abdominoplastia'         },
    { name: 'Liposucción',                    nameEn: 'Liposuction',                   namePt: 'Lipoaspiração',                 key: 'liposuccion'             },
    { name: 'Aumento de Busto',               nameEn: 'Breast Augmentation',           namePt: 'Aumento de Seios',              key: 'aumento_mamario'         },
    { name: 'Reducción de Busto',             nameEn: 'Breast Reduction',              namePt: 'Redução Mamária',               key: 'reduccion_mamaria'       },
    { name: 'Bichectomía',                    nameEn: 'Bichectomy (Cheek Reduction)',  namePt: 'Bichectomia',                   key: 'bichectomia'             },
    { name: 'Blefaroplastia (Párpados)',       nameEn: 'Blepharoplasty (Eyelids)',      namePt: 'Blefaroplastia (Pálpebras)',    key: 'blefaroplastia'          },
    { name: 'Otoplastia (Orejas)',             nameEn: 'Otoplasty (Ear Surgery)',       namePt: 'Otoplastia (Orelhas)',          key: 'otoplastia'              },
    { name: 'Lifting Facial',                 nameEn: 'Facelift',                      namePt: 'Lifting Facial',                key: 'lifting_facial'          },
    { name: 'BBL (Brazilian Butt Lift)',       nameEn: 'BBL (Brazilian Butt Lift)',     namePt: 'BBL (Brazilian Butt Lift)',     key: 'bbl'                     }
  ]
};
}

// Ciudades destino reconocidas (nombre canónico + alias de entrada).
// PRODUCCIÓN: ciudades activas del catálogo de Pangi.
function getCities() {
  // 1) Catálogo real de Pangi (36 ciudades con sus dos banderas).
  //    Se conserva la forma {n, al} que ya usa el motor. Los alias se
  //    generan del propio nombre; los de país NO se replican: 'mexico'
  //    como alias haría que "Ciudad de México" matcheara también Cancún
  //    por subcadena. El emparejamiento por país y por barrio se
  //    resolverá con Claude (capa 2), no ampliando alias a mano.
  try {
    const r = $('🗄️ DB — Cargar Ciudades').first().json;
    if (r && r.success === true && Array.isArray(r.data) && r.data.length > 0) {
      return r.data.filter(x => x && x.city).map(x => ({
        n: x.city,
        al: [String(x.city).toLowerCase()],
        hasDoctors: x.has_doctors === true,
        inCatalog:  x.in_catalog === true
      }));
    }
  } catch (e) { /* nodo ausente o sin ejecutar → fallback */ }

  // 2) Inyección directa por input (compatibilidad).
  const c = inp.catalogCities;
  if (Array.isArray(c) && c.length > 0) return c;
  return [
    {n:'Lima',              al:['lima','peru','perú']},
    {n:'Bogotá',            al:['bogota','bogotá']},
    {n:'Medellín',          al:['medellin','medellín']},
    {n:'Cartagena',         al:['cartagena']},
    {n:'Cali',              al:['cali']},
    {n:'Ciudad de México',  al:['cdmx','ciudad de mexico','ciudad de méxico','mexico city','df','d.f','capital de mexico','capital de méxico']},
    {n:'Cancún',            al:['cancun','cancún']},
    {n:'Monterrey',         al:['monterrey']},
    {n:'Guadalajara',       al:['guadalajara']},
    {n:'Santo Domingo',     al:['santo domingo','dominicana','rep dom','república dominicana']},
    {n:'Buenos Aires',      al:['buenos aires','argentina','baires']},
    {n:'Miami',             al:['miami','florida']},
    {n:'San José, CR',      al:['san jose','san josé','costa rica']},
  ];
}


// Perfil básico del paciente (edad, sexo, condiciones, medicamentos).
// Hoy: cache de sesión, poblado por NOVA/SAGE al preguntar.
// PRODUCCIÓN: perfil real de Pangi → SAGE deja de preguntarlo.
// PENDIENTE (definir con el contacto técnico backend de Pangi): precedencia si ambos existen.
// Por ahora la sesión gana sobre Pangi (refleja lo último que dijo
// el paciente en el chat).
function getPatientProfile(ctx) {
  const p = inp.pangiPatientProfile;
  if (p && typeof p === 'object' && !Array.isArray(p)) {
    return { ...p, ...(ctx.patientProfile || {}) };
  }
  return ctx.patientProfile || {};
}

// ── SETUP ──────────────────────────────────────────────────
const ctx   = inp.sessionContext || {};
const sage  = { ...(ctx.sage || {}) };
const state = sage.state || 'welcome';
const txt   = (inp.messageText || '').toLowerCase().trim();
const fn    = inp.userName ? inp.userName.split(' ')[0] : null;
const nm    = fn ? ` ${fn}` : '';

// ── IDIOMA ─────────────────────────────────────────────────
// Detectar idioma del mensaje actual — actualiza si hay señal clara
const _storedLang = inp.detectedLanguage || ctx.language || inp.userLanguage || 'es';
const _msgLang = (() => {
  const t = (inp.messageText || '').toLowerCase().trim();
  // Señales claras de inglés
  if (/\b(hello|hi there|good morning|good evening|yes please|thank you|i want|i need|i have|quote|schedule|compare|how much|can you|my name|i am|i'm|let's|let me|what is|please help)\b/.test(t)) return 'en';
  if (/^(hello|hi|hey|yes|yeah|nope|sure|ok cool|thanks|quote|schedule|compare|good)$/.test(t)) return 'en';
  // Señales claras de portugués
  if (/\b(olá|ola|oi |bom dia|boa tarde|boa noite|obrigad|quero|sim |não |nao |tudo bem|como vai|me ajuda|cotação)\b/.test(t)) return 'pt';
  if (/^(olá|ola|oi|sim|não|nao|obrigado|obrigada)$/.test(t)) return 'pt';
  return null;
})();
const LANG = _storedLang || _msgLang;

// ── PERFIL BÁSICO DEL PACIENTE ──────────────────────────────
const patProfile   = getPatientProfile(ctx);
const patProfileOk = !!(patProfile.age && patProfile.sex);

// ── SEED DE DESTINOS DESDE NOVA (agendamiento previo) ────────
// MVP CACHE: nova.sched_cities_history / sched_*city. PRODUCCIÓN: DB Pangi.
// Solo si SAGE aún no tiene destinos propios; la respuesta del usuario siempre gana.
if (!sage.preferred_cities) {
  // 1) Ciudad EXPLÍCITA en el mensaje de handoff/inicial → gana sobre el historial NOVA
  const _s1n = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const _s1msg = _s1n(sage.pendingMessage || sage._initial_context || '');
  const _S1_KNOWN = ['Lima','Bogotá','Medellín','Cartagena','Cali','Ciudad de México','Cancún','Monterrey','Guadalajara','Santo Domingo','Buenos Aires','Miami','San José','Barranquilla'];
  const _s1found = _S1_KNOWN.filter(k => _s1msg.includes(_s1n(k)));
  if (_s1found.length > 0) {
    sage.preferred_cities = _s1found.join(', ');
  } else {
    const _novaC = [
      ...((ctx.nova && ctx.nova.sched_cities_history) || []),
      ctx.nova && ctx.nova.sched_selected_city,
      ctx.nova && ctx.nova.sched_city
    ].filter(Boolean);
    // El historial NOVA NUNCA se auto-asigna: queda como sugerencia y el usuario confirma.
    if (_novaC.length > 0) sage._nova_cities_suggest = [...new Set(_novaC)].join(', ');
  }
}

// ── NORMALIZACIÓN ──────────────────────────────────────────
const normalize = (s) => String(s)
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

// ── ALIAS DE CIUDAD ─────────────────────────────────────────
// Reconocimiento de lenguaje, NO catálogo: Pangi no tiene alias.
// `canon` es una lista de candidatos en orden de preferencia; el
// destino debe existir en el catálogo activo. Con Pangi, 'cdmx'
// resuelve a 'Mexico City'; con el literal de fallback, a
// 'Ciudad de México'. Mismo código, ambos mundos.
//
// PENDIENTE (capa 2): 'Buenos Aires' no resuelve contra Pangi, que
// solo tiene los barrios Balvanera/Barracas/Palermo. Tampoco los
// países. Se resolverá con Claude + caché, no ampliando esta lista.
const CITY_ALIASES = [
  { canon: ['Mexico City', 'Ciudad de México'], al: ['cdmx', 'df', 'ciudad de mexico'] },
  { canon: ['Santo Domingo'],                   al: ['rep dom', 'republica dominicana'] },
  { canon: ['Buenos Aires'],                    al: ['baires', 'caba'] },
];

const _CITY_NAMES  = getCities().map(c => c.n);
const _aliasTarget = (a) => a.canon.find(cn =>
  _CITY_NAMES.some(nn => normalize(nn) === normalize(cn))) || null;
const _escRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Expande alias dentro de un texto YA normalizado, hacia el nombre del
// catálogo. Usa límites de palabra: 'df' como subcadena matchearía
// dentro de "pdf", y 'caba' dentro de "acaba".
const applyCityAliases = (txtN) => {
  let out = String(txtN || '');
  for (const a of CITY_ALIASES) {
    const target = _aliasTarget(a);
    if (!target) continue;
    for (const raw of a.al) {
      const aN = normalize(raw);
      if (!aN) continue;
      out = out.replace(new RegExp('\\b' + _escRe(aN) + '\\b', 'g'), normalize(target));
    }
  }
  return out;
};

const txtN = normalize(txt);

