  reduccion_mamaria:       ['breast reduction','mamoplastia redutora','redução mamária'],
  bichectomia:             ['bichectomy','cheek reduction','buccal fat removal','bichec'],
  blefaroplastia:          ['blepharoplasty','eyelid surgery','eye lift','blefaro'],
