// ── MATCH DE PROCEDIMIENTO ──────────────────────────────────
const matchProcedure = (inputTxtN, procs) => {
  let matched = null;
  const num = parseInt(inputTxtN);
  if (!isNaN(num) && num >= 1 && num <= procs.length) matched = procs[num - 1];
  if (!matched) matched = procs.find(p =>
    inputTxtN.includes(normalize(p.name))   ||
    inputTxtN.includes(normalize(p.nameEn)) ||
    inputTxtN.includes(normalize(p.namePt)) ||
    inputTxtN.includes(p.key.replace(/_/g, ' '))
  );
  if (!matched) matched = procs.find(p => {
    // Excluir palabras genéricas compartidas por varios procedimientos:
    // "aumento de glúteos" NO debe matchear "Aumento de Busto" por la palabra "aumento".
    const words = normalize(p.name).split(' ').filter(w => w.length > 4 &&
      !/^(aumento|reduccion|reducao)$/.test(w));
    return words.some(w => inputTxtN.includes(w));
  });
  if (!matched) matched = procs.find(p => {
    const aliases = PROCEDURE_ALIASES[p.key] || [];
    return aliases.some(a => {
      const aN = normalize(a);
      if (aN.length >= 4 && inputTxtN.includes(aN)) return true;
      if (inputTxtN.length >= 5) {
        // Excluir genéricas también aquí: 'aumento' del usuario no debe matchear
        // aliases de otros procedimientos ('aumento de mamas', 'mamoplastia de aumento').
        const userWords = inputTxtN.split(/[\s,]+/).filter(w => w.length >= 4 &&
          !/^(aumento|reduccion|reducao)$/.test(w));
        return userWords.some(w => aN.includes(w));
      }
      return false;
    });
  });
  if (!matched) matched = procs.find(p => {
    const keyN = normalize(p.key.replace(/_/g, ''));
    const GENERIC = /^(cirugia|cirurgia|plastica|plastic|surgery|dental|estetica|aesthetic|procedimiento|procedure|tratamiento|treatment|operacion|cotizar|cotizacion)$/;
    const userWords = inputTxtN.split(/[\s,]+/).filter(w => w.length >= 5 && !GENERIC.test(w));
    return userWords.some(w => keyN.startsWith(w.substring(0, 7)));
  });
  return matched;
};

// ── ESCAPE INTENTS ──────────────────────────────────────────
const isEscapeToAtlas = /^(atlas|comparar?|compare|destinos?|destinations?|quiero comparar|i want to compare|want to compare|quero comparar|ver destinos)$/i.test(txt);

// ── DETECCIÓN DE ESPECIALIDAD ───────────────────────────────
const detectSpecialty = (inputTxtN) => {
  const kDental  = /dental|diente|muela|implant|ortodoncia|corona|crown|carilla|veneer|blanquea|endodoncia|extrac|puente|protesis|limpieza|conducto|tooth|teeth|braces|aligner|whitening|root canal|bridge|denture|deep clean|wisdom|dente|clareamento|canal|coroa|protese|limpeza|aparelho|ortodontia|extracao|faceta|carie|caries|dolor.*muela|muela.*dolor|empaste|relleno|sarro|\bencia|sangra|boca|dol.*dient|dient.*dol/i;
  const kPlastic = /plastic|cirugia|rinoplas|rinplas|liposu|abdominoplas|mamario|mamas|busto|seno|bichec|blefaroplas|blefaro|otoplas|lifting|bbl|nariz|glut|rhinoplasty|liposuction|tummy tuck|breast|facelift|face lift|blepharoplasty|ear surgery|nose job|butt lift|augmentation|mamoplastia|lipoaspiracao|seios|arrug|flacid|rejuven|papada|mejill|parpad|orej|aesthetic|estetica|apariencia/i;
  const isDental  = kDental.test(inputTxtN)  || inputTxtN === '1';
  const isPlastic = kPlastic.test(inputTxtN) || inputTxtN === '2';
  if (isDental && !isPlastic) return 'dental';
  if (isPlastic) return 'plastic_surgery';
  if (isDental) return 'dental';
  return null;
};

let rt  = '';
let nag = 'SAGE';
let nss = 'sage_active';
let shouldSaveIntake = false;
let intakePayload    = null;

// ═══════════════════════════════════════════════════════════════
// GUARD CONVERSACIONAL (pre-estado)
// CAUSA RAÍZ: los estados de trabajo de SAGE solo sabían validar el dato esperado.
// Un cambio de intención o una expresión de duda no tenían salida → bucle.
// El router mantiene el control en SAGE mientras su flujo está activo (por diseño,
// para no abandonar flujos a medias), así que el escape debe resolverse AQUÍ.
// Precisión: exige verbo de intención + término de agendamiento en la misma frase.
