const _G_WORK   = ['welcome','handoff_received','selecting_specialty','selecting_procedure','gathering_profile','procedure_confirmed','questioning'];
const _G_SELECT = ['welcome','handoff_received','selecting_specialty','selecting_procedure'];

const _gWantsSched = _G_WORK.includes(state) && (
  /(quiero|queria|quisiera|prefiero|prefiro|mejor|en realidad|primero|necesito|me gustaria|i want|i need|i'd rather|actually|first)[^.!?]{0,40}(agendar|agenda\b|cita\b|citas\b|reservar|turno\b|appointment|schedule|book\b|marcar consulta)/.test(txtN)
  || /^(agendar|quiero agendar|agendar cita|agendar una cita|schedule|book an appointment|marcar consulta)\b/.test(txtN)
);
const _gUnsure = _G_SELECT.includes(state) && (
  /(no se |no se$|no lo se|nose |no estoy segur|ni idea|no tengo claro|no sabria|ayudame a decidir|orientame|que me recomiendas|cual me conviene|no entiendo|estoy perdid|not sure|i dont know|i don't know|no idea|help me decide|nao sei|nao tenho certeza)/.test(txtN)
);

let _guardHandled = false;

if (_gWantsSched) {
  // ESCAPE A NOVA — la solicitud a medias queda guardada, no se pierde nada
  nag = 'NOVA';
  nss = 'handoff_received';
  sage.state = 'handoff_to_nova';
  sage._skip_nlg_once = true;
  const _gCities = (sage.preferred_cities || '').split(',').map(s => s.trim())
