    sched_cities_history: [...new Set([ ...(((ctx.nova || {}).sched_cities_history) || []), ..._gCities ])] };
  const _gProc = sage.procedure_name
    ? (LANG === 'en' ? `Your *${sage.procedure_name}* request stays saved — you can pick it up whenever you want.\n\n`
      : LANG === 'pt' ? `Sua solicitação de *${sage.procedure_name}* fica salva — pode retomar quando quiser.\n\n`
      : `Tu solicitud de *${sage.procedure_name}* queda guardada — puedes retomarla cuando quieras.\n\n`)
    : '';
  rt = (LANG === 'en'
    ? `Of course${nm}! 🗓️ Connecting you with *NOVA* to schedule your appointment.\n\n${_gProc}Shall we start? 👍`
    : LANG === 'pt'
    ? `Claro${nm}! 🗓️ Vou te conectar com *NOVA* para agendar sua consulta.\n\n${_gProc}Começamos? 👍`
    : `¡Claro${nm}! 🗓️ Te conecto con *NOVA* para agendar tu cita.\n\n${_gProc}¿Empezamos? 👍`);
  _guardHandled = true;

} else if (_gUnsure) {
  // INCERTIDUMBRE — orientación, nunca "no encontré ese procedimiento"
  sage._skip_nlg_once = true;
  rt = LANG === 'en'
    ? `No problem${nm} 🙂 Let's figure it out together.\n\nTell me in your own words what's bothering you or what you'd like to improve. For example:\n\n• _"my molar hurts"_@NL• _"I want my nose to look smaller"_@NL• _"I chipped a tooth"_\n\nFrom that I'll identify the procedure and prepare your quote.`
    : LANG === 'pt'
    ? `Sem problema${nm} 🙂 Vamos descobrir juntos.\n\nMe conte com suas palavras o que incomoda ou o que gostaria de melhorar. Por exemplo:\n\n• _"meu dente dói"_@NL• _"quero que meu nariz pareça menor"_@NL• _"quebrei um dente"_\n\nCom isso identifico o procedimento e preparo sua cotação.`
    : `Sin problema${nm} 🙂 Lo resolvemos juntos.\n\nCuéntame con tus palabras qué te molesta o qué te gustaría mejorar. Por ejemplo:\n\n• _"me duele una muela"_@NL• _"quiero que mi nariz se vea más pequeña"_@NL• _"se me partió un diente"_\n\nCon eso identifico el procedimiento y preparo tu cotización.`;
  _guardHandled = true;
}

if (!_guardHandled) switch(state) {

  // ── BIENVENIDA ─────────────────────────────────────────────
  case 'welcome': {
    if (!patProfileOk) {
      sage.state = 'gathering_profile';
      sage.profile_step = 1;
      // ✅ FIX: bullets en los 3 idiomas
      rt = LANG === 'en'
        ? `Hello${nm}, I'm *SAGE* 🩺 your medical quotes specialist at Pangi.\n\nI need two quick things to personalize your request 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)\n• *Do you have any known medical conditions or take any medications?*\n\n_If none, just write "none"._`
        : LANG === 'pt'
        ? `Olá${nm}, sou *SAGE* 🩺 sua especialista em cotações médicas da Pangi.\n\nPreciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)\n• *Você tem alguma condição médica conhecida ou toma medicamentos?*\n\n_Se não tiver nenhuma, escreva "nenhuma"._`
        : `Hola${nm}, soy *SAGE* 🩺 tu especialista en cotizaciones de Pangi.\n\nNecesito dos datos rápidos para personalizar tu solicitud 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)\n• *¿Tienes alguna condición médica o tomas medicamentos?*\n\n_Si no tienes nada, escribe "ninguna"._`;
      break;
    }
    rt = t('welcome', {nm});
    sage.state = 'selecting_specialty';
    break;
  }

  // ── HANDOFF RECIBIDO ────────────────────────────────────────
  case 'handoff_received': {
    const rawPending  = sage.pendingMessage || '';
    sage.pendingMessage = null;

    const isGenericInput = /^(1|2|s[íi]|si|yes|ok|dale|listo|ready|pronto|sure|claro|adelante|sim|\d)$/i.test(txt.trim());
    const txtNH   = isGenericInput ? '' : txtN;
    const pendTxtN = normalize(rawPending);

    const spTxt  = detectSpecialty(txtNH);
    const spPend = detectSpecialty(pendTxtN);
    const workingTxtN = spTxt ? txtNH : (spPend ? pendTxtN : txtNH);
    const workingSp   = spTxt || spPend;

    if (workingSp) {
      const procsH = PROCEDURES[workingSp];
      sage.specialty = workingSp;
      const matchedH = matchProcedure(workingTxtN, procsH) ||
                       (workingTxtN !== pendTxtN ? matchProcedure(pendTxtN, procsH) : null);

      if (matchedH) {
        sage.procedure_key  = matchedH.key;
        sage.procedure_name = procName(matchedH);
        sage._initial_context = [rawPending, inp.messageText].filter(Boolean).join(' ').trim();

        if (!patProfileOk) {
          sage._prof_sp        = workingSp;
          sage._prof_proc_key  = matchedH.key;
          sage._prof_proc_name = procName(matchedH);
          sage.state        = 'gathering_profile';
          sage.profile_step = 1;
          const _pn = procName(matchedH);
          // ✅ FIX: bullets en los 3 idiomas
          rt = LANG === 'en'
            ? `${t('intro_brief', {nm})}\n\n*${_pn}* ✅\n\nBefore we start, I need two quick things 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)\n• *Do you have any known medical conditions or take any medications?*\n\n_If none, just write "none"._`
            : LANG === 'pt'
            ? `${t('intro_brief', {nm})}\n\n*${_pn}* ✅\n\nAntes de começar, preciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)\n• *Você tem alguma condição médica ou toma medicamentos?*\n\n_Se não tiver nenhuma, escreva "nenhuma"._`
            : `${t('intro_brief', {nm})}\n\n*${_pn}* ✅\n\nAntes de empezar, necesito dos datos rápidos 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)\n• *¿Tienes alguna condición médica o tomas medicamentos?*\n\n_Si no tienes ninguna, escribe "ninguna"._`;
        } else if (!sage.preferred_cities && sage._nova_cities_suggest) {
          // Perfil ya conocido pero destinos sin confirmar → confirmar la sugerencia de NOVA
          sage._prof_sp        = workingSp;
          sage._prof_proc_key  = matchedH.key;
          sage._prof_proc_name = procName(matchedH);
          sage._initial_context = [rawPending, inp.messageText].filter(Boolean).join(' ').trim();
