    }

    // Sin especialidad → verificar contexto previo recuperable
    const prevKey   = ctx.sage?.procedure_key   || null;
    const prevName  = ctx.sage?.procedure_name  || null;
    const prevState = ctx.sage?.state           || '';
    const prevData  = ctx.sage?.collected_data  || {};

    if (prevKey && prevName) {
      sage.specialty          = ctx.sage?.specialty         || sage.specialty;
      sage.procedure_key      = prevKey;
      sage.procedure_name     = prevName;
      sage.collected_data     = prevData;
