    }
    sage.specialty = sp;
    const procsForSp  = PROCEDURES[sp];
    // Si el mensaje es SOLO la especialidad ("dental", "1", "cirugía plástica"), no se
    // adivina el procedimiento: la palabra suelta "dental" matchea "Implante Dental" y
    // saltaba directo a ese procedimiento sin mostrar la lista.
    const _spOnly = /^(1|2|dental|odontologia|odontologica|odontologico|dentista|plastica|cirugia plastica|cirugia estetica|estetica|plastic|plastic surgery|dentistry|odonto)[\s.!]*$/.test(txtN);
    const directMatch = _spOnly ? null : matchProcedure(txtN, procsForSp);
    if (directMatch) {
      sage.procedure_key  = directMatch.key;
      sage.procedure_name = procName(directMatch);
      sage.state          = 'procedure_confirmed';
      sage._initial_context = sage._initial_context || inp.messageText || '';
      rt = t('procedure_ready', {nm, procedure: procName(directMatch)});
      break;
    }
    const emoji = sp === 'dental' ? '🦷' : '💉';
    const list  = procsForSp.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
    rt = t('procedure_prompt', {nm, emoji, list});
    sage.state = 'selecting_procedure';
    break;
  }

  // ── SELECCIÓN DE PROCEDIMIENTO ─────────────────────────────
  case 'selecting_procedure': {
    const sp    = sage.specialty || 'dental';
    const procs = PROCEDURES[sp] || [];
    const matched = matchProcedure(txtN, procs);

    if (!matched) {
      const otherSp    = sp === 'dental' ? 'plastic_surgery' : 'dental';
      const crossMatch = matchProcedure(txtN, PROCEDURES[otherSp]);
      if (crossMatch) {
        sage.specialty      = otherSp;
        sage.procedure_key  = crossMatch.key;
        sage.procedure_name = procName(crossMatch);
        sage.state          = 'procedure_confirmed';
        rt = t('procedure_ready', {nm, procedure: procName(crossMatch)});
        break;
      }
      const emoji = sp === 'dental' ? '🦷' : '💉';
      const list  = procs.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
      rt = t('procedure_error', {nm, emoji, list});
      break;
    }

    sage.procedure_key  = matched.key;
    sage.procedure_name = procName(matched);
    sage.state          = 'procedure_confirmed';
    sage._initial_context = sage._initial_context || inp.messageText || '';
    rt = t('procedure_ready', {nm, procedure: procName(matched)});
    break;
  }

  // ── PROCEDIMIENTO CONFIRMADO ────────────────────────────────
  case 'procedure_confirmed': {
    if (!patProfileOk) {
      sage._prof_sp         = sage.specialty        || null;
      sage._prof_proc_key   = sage.procedure_key    || null;
      sage._prof_proc_name  = sage.procedure_name   || null;
      sage.state      = 'gathering_profile';
      sage.profile_step = 1;
      // ✅ FIX: bullets en los 3 idiomas
      rt = LANG === 'en'
        ? `Before we start your *${sage._prof_proc_name || 'procedure'}* quote, I need two quick things 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)\n• *Do you have any known medical conditions or take any medications?*\n\n_If none, just write "none"._`
        : LANG === 'pt'
        ? `Antes de começar sua cotação de *${sage._prof_proc_name || 'procedimento'}*, preciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)\n• *Você tem alguma condição médica ou toma medicamentos?*\n\n_Se não tiver nenhuma, escreva "nenhuma"._`
        : `Antes de empezar tu cotización de *${sage._prof_proc_name || 'procedimiento'}*, necesito dos datos rápidos 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)\n• *¿Tienes alguna condición médica o tomas medicamentos?*\n\n_Si no tienes ninguna, escribe "ninguna"._`;
      break;
    }
    if (!procData) {
      // Anti-loop: si la DB no devuelve datos tras 2 intentos,
      // la procedure_key es inválida → resetear a selección de especialidad
      const attempts = (sage._proc_load_attempts || 0) + 1;
      sage._proc_load_attempts = attempts;
      if (attempts >= 2) {
        sage.state              = 'selecting_specialty';
        sage.procedure_key      = null;
        sage.procedure_name     = null;
        sage._proc_load_attempts = 0;
        rt = LANG === 'en'
          ? `Sorry${nm}, I couldn't load that procedure. Let's start over.\n\n*Which specialty do you need a quote for?*\n🦷 Type *1* or *dental*\n💉 Type *2* or *plastic surgery*`
          : LANG === 'pt'
          ? `Desculpe${nm}, não consegui carregar o procedimento. Vamos recomeçar.\n\n*Para qual especialidade você precisa de cotação?*\n🦷 Escreva *1* ou *dental*\n💉 Escreva *2* ou *cirurgia plástica*`
          : `Lo sentimos${nm}, no pude cargar ese procedimiento. Volvamos a empezar.\n\n*¿Para qué especialidad necesitas cotizar?*\n🦷 Escribe *1* o *dental*\n💉 Escribe *2* o *cirugía plástica*`;
      } else {
        rt = t('kb_loading', {nm});
      }
      break;
    }

    const rawQ = parseArr(procData.critical_questions);
    const isObjFmt = rawQ.length > 0 && typeof rawQ[0] === 'object';
    let questions, infoKeys;
    if (isObjFmt) {
      questions = rawQ.map(q => q.question);
      infoKeys  = rawQ.map(q => q.key);
    } else {
      questions = rawQ;
      infoKeys  = parseArr(procData.required_info);
    }

    sage.critical_questions = questions;
    sage.required_info      = infoKeys;
    // Filtrar exámenes condicionales que no aplican al perfil conocido
    // (ej: 'mamografia_si_mayor_35' no se lista ni puntúa si la paciente tiene 32).
    const _ageEx = (ctx.patientProfile || {}).age || null;
    sage.required_exams     = parseArr(procData.required_exams).filter(e => {
      const _mAge = String(e).match(/si_?\s*mayor_?\s*(\d{2})/i);
      return !(_mAge && _ageEx && _ageEx < parseInt(_mAge[1]));
    });
    sage.typical_recovery   = procData.typical_recovery_days || 3;
    sage.collected_data     = {};
    sage.exams_covered      = []; // FIX: los adjuntos de la solicitud ANTERIOR no cuentan para esta
    sage._q_rounds          = 0;  // rondas de preguntas de ESTA solicitud
    // DATOS TRANSVERSALES DEL PACIENTE (no del procedimiento): si ya los conocemos de una
    // solicitud anterior, se siembran para no volver a preguntarlos. MVP CACHE en
    // ctx.patientProfile; PRODUCCIÓN: perfil del paciente en la DB de Pangi.
    const _XVAL = (ctx.patientProfile || {}).smoker || null;
    if (_XVAL) {
      (sage.required_info || []).forEach(k => {
        if (/^(fumador|fumadora|fuma|smoker|smoking|fumante|tabaquismo)$/i.test(String(k))) {
          sage.collected_data[k] = _XVAL;
        }
      });
    }
    sage.current_q_index    = 1;
    sage.state              = 'questioning';

    const intro = LANG === 'en'
      ? `Let's prepare your *${sage.procedure_name}* quote:`
      : LANG === 'pt'
      ? `Vamos preparar sua cotação de *${sage.procedure_name}*:`
      : (procData.sage_intro_message || `Empecemos con *${sage.procedure_name}*:`);

    const batchLabel = LANG === 'en'
      ? 'To get precise quotes, please answer:'
      : LANG === 'pt'
      ? 'Para obter cotações precisas, responda:'
      : 'Para cotizar con precisión, necesito saber:';

    const allQsFmt = questions.map(q => `• ${q}`).join('\n');
    rt = `${intro}\n\n${batchLabel}\n${allQsFmt}`;

    shouldSaveIntake = true;
    intakePayload = { operation: 'saveMedicalIntake', params: {
      userId: inp.userId, sessionId: inp.sessionId, specialty: sage.specialty,
      procedureName: sage.procedure_name, collectedData: {}, missingItems: sage.required_exams, score: 0
    }};
    break;
  }

  // ── Q&A — Multi-extracción v3.0 ──────────────────────────────
  case 'questioning': {
    if (isEscapeToAtlas) {
      const score = sage.completeness_score || 0;
      rt  = t('escape_offer', {nm, procedure: sage.procedure_name || '—', score});
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
      ctx.atlas = { ...(ctx.atlas || {}), state: 'handoff_received' };
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: sage.collected_data || {},
        missingItems: sage.required_exams || [],
        score,
        status: 'in_progress'
      }};
      break;
    }
    if (sage._qa_just_started) {
      sage._qa_just_started = false;
    }
    const questions  = sage.critical_questions || [];
    const infoKeys   = sage.required_info      || [];
    const collected  = { ...(sage.collected_data || {}) };
    const totalQ     = questions.length;
    const answeredCount = infoKeys.filter(k => collected[k] !== undefined).length;
    const baseScore     = Math.round((answeredCount / totalQ) * 85);
    const _examPending  = /buscar|busco|luego|despues|mas tarde|todavia|aun no|no la tengo|no lo tengo|compartir|enviar|mandar|later|will look|will find|will send|will share|depois|procurar|assim que/i.test(txtN);
    const examBonus     = (!_examPending && (sage.required_exams || []).some(e =>
      txtN.includes(normalize(e).substring(0, 5))
    )) ? 15 : 0;
    const score = Math.min(100, baseScore + examBonus);
    sage.completeness_score = score;
    rt = '';
    shouldSaveIntake = answeredCount > 0;
    if (answeredCount > 0) {
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: collected,
        missingItems: sage.required_exams || [],
        score
      }};
    }
    break;
  }

  // ── RESUMEN ─────────────────────────────────────────────────
  case 'summary': {
    // FIX confirmación accidental: /si/ sin \b matcheaba "nece-si-tas" y publicaba
    // la solicitud con un mensaje que NO era confirmación. Ahora: (1) el token debe
    // ser palabra completa y (2) el mensaje debe ser SOLO confirmación/cortesía —
    // si trae contenido adicional (preguntas, anuncios de envío), va a la rama de
    // "agregar información" y Claude responde de forma natural.
    const _sumN = normalize(txt);
    const _CONFIRM_TOKENS = /\b(confirmar|confirmo|confirmado|confirma|confirm|publicar|publica|publicalo|enviar|envialo|envia|send|submit|si|yes|sim|listo|lista|ok|okey|vale|dale|adelante|perfecto|claro|correcto|de acuerdo|esta|bien|todo|asi|gracias|por|favor|porfa|please|ya)\b/g;
    const _sumResid = _sumN.replace(_CONFIRM_TOKENS, ' ').replace(/[\s,.!¡¿?]+/g, ' ').trim();
    const isConfirm = /\b(confirmar|confirmo|confirmado|confirm|publicar|publica|enviar|si|yes|sim|listo|ok|dale|adelante)\b/.test(_sumN) && _sumResid === '';
    // Señales adicionales en el resumen: escape a agendamiento y cambio de destinos
    const _wantsSchedSum = /\b(agendar|agende|agenda|cita|reservar|reserva|turno|schedule|book|appointment)\b/.test(_sumN);
    // Antes había aquí una cuarta lista hardcodeada de ciudades.
    const _catSum    = getCities();
    const _KNOWN_SUM = _catSum.map(c => c.n);
    // Para MOSTRAR: solo las del catálogo curado que tienen médicos
    // (nombres reconocibles). Se ACEPTAN las demás igual.
    const KNOWN_CITIES_SUM = _catSum
      .filter(c => c.hasDoctors === true && c.inCatalog === true).map(c => c.n);
    // Alias expandidos hacia el nombre del catálogo, con límites de palabra.
    const _sumNx = applyCityAliases(_sumN);
    const _sumCities = _KNOWN_SUM.filter(k => _sumNx.includes(normalize(k)));
    const _cityIntent = /\b(ciudad|ciudades|cidade|cidades|city|cities|destino|destinos|destination|cambia|cambiar|cambialo|cambiemos|solamente|unicamente|en lugar|mejor en|cotiza en|cotizar en|quiero en|hazlo en)\b/.test(_sumN);
    if (isConfirm) {
      rt = t('published', {nm, name_comma: fn ? ', ' + fn : '', procedure: sage.procedure_name});
      sage.state = 'complete';
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, status: 'submitted', score: sage.completeness_score || 0
      }};
    } else if (_wantsSchedSum) {
      // ESCAPE A NOVA desde el resumen. Antes solo existía en 'complete': el usuario que
      // pedía agendar desde el resumen quedaba ATRAPADO en un bucle sin salida.
      nag = 'NOVA';
      nss = 'handoff_received';
      sage.state = 'handoff_to_nova';
      sage._skip_nlg_once = true; // respuesta determinística: Claude no debe pisar el handoff
      const _sageCityS = (sage.preferred_cities || '').split(',').map(s => s.trim())
        .filter(s => s && !/sin preferencia|aberto|open to|any destination/i.test(s));
      ctx.nova = { ...(ctx.nova || {}), state: 'welcome', pendingMessage: inp.messageText,
        sched_cities_history: [...new Set([ ...(((ctx.nova || {}).sched_cities_history) || []), ..._sageCityS ])] };
      rt = LANG === 'en'
        ? `Of course${nm}! 🗓️ Connecting you with *NOVA* to schedule your appointment.\n\nNote: your *${sage.procedure_name}* request stays saved but *not published yet* — come back and type *confirm* anytime.\n\nShall we start? 👍`
        : LANG === 'pt'
        ? `Claro${nm}! 🗓️ Vou te conectar com *NOVA* para agendar sua consulta.\n\nAtenção: sua solicitação de *${sage.procedure_name}* fica salva mas *ainda não publicada* — volte e escreva *confirmar* quando quiser.\n\nComeçamos? 👍`
        : `¡Claro${nm}! 🗓️ Te conecto con *NOVA* para agendar tu cita.\n\nOjo: tu solicitud de *${sage.procedure_name}* queda guardada pero *sin publicar* — vuelve y escribe *confirmar* cuando quieras.\n\n¿Empezamos? 👍`;
    } else if (_sumCities.length > 0 && _cityIntent) {
      // CAMBIO DE DESTINOS pedido desde el resumen → actualización DETERMINÍSTICA.
      // Antes caía al NLG y Claude "prometía" cambios que nunca ocurrían (bucle infinito).
      sage.preferred_cities = _sumCities.join(', ');
      sage._skip_nlg_once = true;
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, collectedData: sage.collected_data || {}, score: sage.completeness_score || 0
      }};
      const _scNow = sage.completeness_score || 0;
      rt = LANG === 'en'
        ? `✅ *Destinations updated:* ${sage.preferred_cities}\n\n📊 *Completeness: ${_scNow}%*\n\nYou can add more information now — or type *confirm* to publish as is.`
        : LANG === 'pt'
        ? `✅ *Destinos atualizados:* ${sage.preferred_cities}\n\n📊 *Completude: ${_scNow}%*\n\nVocê pode adicionar mais informações agora — ou escreva *confirmar* para publicar como está.`
        : `✅ *Destinos actualizados:* ${sage.preferred_cities}\n\n📊 *Completitud: ${_scNow}%*\n\nSi quieres agregar más información puedes hacerlo ahora — o escribe *confirmar* para publicar tal como está.`;
    } else if (_cityIntent && _sumCities.length === 0) {
      // PIDIÓ CAMBIAR DE CIUDAD PERO NINGUNA COINCIDE CON EL CATÁLOGO.
      // Antes caía al else genérico: el mensaje se guardaba como
      // 'detalle_adicional' —o sea, como dato clínico—, la completitud
      // subía 8% por una ciudad inexistente, y sin _skip_nlg_once el NLG
      // tomaba control y CONFIRMABA un destino que nunca se registró.
      // Respuesta determinística: se dice la verdad y no se toca nada.
      const _availNow = KNOWN_CITIES_SUM.length > 0
        ? KNOWN_CITIES_SUM.join(', ')
        : _KNOWN_SUM.join(', ');
      const _keepCities = sage.preferred_cities || '—';
      sage._skip_nlg_once = true;
      rt = LANG === 'en'
        ? `I couldn't find that city among our destinations 🔍\n\n📍 *Available destinations:* ${_availNow}\n\nYour destinations remain: *${_keepCities}*\n\nWrite one from the list, or type *confirm* to publish as is.`
        : LANG === 'pt'
        ? `Não encontrei essa cidade entre nossos destinos 🔍\n\n📍 *Destinos disponíveis:* ${_availNow}\n\nSeus destinos continuam: *${_keepCities}*\n\nEscreva um da lista, ou escreva *confirmar* para publicar como está.`
        : `No encontré esa ciudad entre nuestros destinos 🔍\n\n📍 *Destinos disponibles:* ${_availNow}\n\nTus destinos siguen siendo: *${_keepCities}*\n\nEscribe uno de la lista, o escribe *confirmar* para publicar tal como está.`;
    } else {
      const prev = sage.collected_data || {};
      prev['detalle_adicional'] = inp.messageText;
      sage.collected_data = prev;
      const newScore = Math.min(100, (sage.completeness_score || 70) + 8);
      sage.completeness_score = newScore;
      rt = t('added_details', {nm, score: newScore});
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, collectedData: prev, score: newScore
      }};
    }
    break;
  }

  // ── COMPLETO ────────────────────────────────────────────────
  case 'complete':
  case 'waiting_for_quotes': {
    // PRIORIDAD: intención de AGENDAR (verbo de acción) → handoff a NOVA.
    // Se evalúa ANTES que wantsAtlas para que "quiero agendar" no se lea como "quiero [comparar]".
    const wantsSchedule = /\b(agendar|agende|agenda|cita|reservar|reserva|turno|schedule|book|appointment|marcar consulta|marcar uma|agendar consulta)\b/i.test(txtN);

    if (wantsSchedule) {
      // Ruta SAGE → NOVA (agendamiento). MERGE de contexto: NOVA leerá pendingMessage.
      nag = 'NOVA';
      nss = 'handoff_received';
      sage.state = 'handoff_to_nova';
      // Compartir con NOVA las ciudades de la cotización (fuente de sugerencia de agendamiento)
      const _sageCityL = (sage.preferred_cities || '').split(',').map(s => s.trim())
        .filter(s => s && !/sin preferencia|aberto|open to|any destination/i.test(s));
      ctx.nova = { ...(ctx.nova || {}), state: 'welcome', pendingMessage: inp.messageText,
        sched_cities_history: [...new Set([ ...(((ctx.nova || {}).sched_cities_history) || []), ..._sageCityL ])] };
      rt = LANG === 'en'
        ? `Of course${nm}! 🗓️ Connecting you with *NOVA* to schedule your appointment.\n\nNOVA will find available doctors and book for you. One moment!`
        : LANG === 'pt'
        ? `Claro${nm}! 🗓️ Vou te conectar com *NOVA* para agendar sua consulta.\n\nNOVA vai encontrar médicos disponíveis e reservar. Um momento!`
        : `¡Claro${nm}! 🗓️ Te conecto con *NOVA* para agendar tu cita.\n\nNOVA buscará médicos disponibles y hará la reserva.\n\n¿Empezamos? 👍`;
      break;
    }

    const wantsAtlas = /\batlas\b|\bcompar|\bdestino|\bcomparar\b|\bcompare\b|\bdestination|connect me|\bdestinos\b/i.test(txtN);
    const allProcs   = [...PROCEDURES.dental, ...PROCEDURES.plastic_surgery];
    const newProcMatch = (!wantsAtlas && !wantsSchedule) ? matchProcedure(txtN, allProcs) : null;

    if (wantsAtlas) {
      rt  = t('connecting_atlas', {nm, procedure: sage.procedure_name});
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
      ctx.atlas = { ...(ctx.atlas || {}), state: 'handoff_received' };
    } else if (newProcMatch && newProcMatch.key !== sage.procedure_key) {
      const newSp = PROCEDURES.dental.find(p => p.key === newProcMatch.key) ? 'dental' : 'plastic_surgery';
      sage.specialty           = newSp;
      sage.procedure_key       = newProcMatch.key;
      sage.procedure_name      = newProcMatch.name;
      sage.state               = 'procedure_confirmed';
      sage.collected_data      = {};
      sage.current_q_index     = 1;
      sage.completeness_score  = 0;
      sage.intake_id           = null;
      if (sage.preferred_cities) {
        // Los destinos de la solicitud ANTERIOR se sugieren de nuevo, nunca se heredan en silencio
        sage._prof_sp        = newSp;
        sage._prof_proc_key  = newProcMatch.key;
        sage._prof_proc_name = procName(newProcMatch);
        const _sugP = sage.preferred_cities;
        sage._nova_cities_suggest = _sugP;
        sage.preferred_cities = null;
        sage.state        = 'gathering_profile';
        sage.profile_step = 'cities_pending';
        rt = t('intro_brief', {nm}) + '\n\n' + (LANG === 'en'
          ? `*${procName(newProcMatch)}* ✅\n\nYour previous request used *${_sugP}* as destination. *Keep it for this one too?*\n\n_Reply "yes" to confirm, or write other cities._`
          : LANG === 'pt'
          ? `*${procName(newProcMatch)}* ✅\n\nSua solicitação anterior usou *${_sugP}* como destino. *Mantenho para esta também?*\n\n_Responda "sim" para confirmar, ou escreva outras cidades._`
          : `*${procName(newProcMatch)}* ✅\n\nTu solicitud anterior usó *${_sugP}* como destino. *¿Lo mantengo para esta también?*\n\n_Responde "sí" para confirmar, o escribe otras ciudades._`);
      } else {
        rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_ready', {nm, procedure: procName(newProcMatch)});
      }
    } else if (/(otra cotizacion|nueva cotizacion|otra solicitud|nueva solicitud|cotizar otra|cotizar algo|cotizar mas|otro procedimiento|otra cosa|another quote|new quote|new request|outra cotacao|nova cotacao)/.test(txtN)) {
      // Pidió cotizar algo más pero sin nombrar el procedimiento: preguntar cuál,
      // en vez de responder con el mensaje genérico sobre ATLAS.
      sage.state = 'selecting_specialty';
      rt = t('welcome', {nm});
    } else {
      rt = t('wait_quotes', {nm});
      sage.state = 'waiting_for_quotes';
    }
    break;
  }

  // ── RECOPILACIÓN DE PERFIL — Batch v3.0 ─────────────────────
  case 'gathering_profile': {
    const pStep   = sage.profile_step || 1;
    const profile = { ...(ctx.patientProfile || {}) };

    if (pStep === 1) {
      sage.profile_step = 'extracting';
      rt = '';
      break;
    }

    if (pStep === 'extracting') {
      rt = '';
      break;
    }

    if (pStep === 'cities_pending') {
      // Intentar extraer ciudad del pendingMessage o _initial_context antes de preguntar
      const _novaCitiesTxt = [
        ...((ctx.nova && ctx.nova.sched_cities_history) || []),
        ctx.nova && ctx.nova.sched_selected_city,
        ctx.nova && ctx.nova.sched_city
      ].filter(Boolean).join(', ');
      const _preText = [sage.pendingMessage || sage._initial_context || '', _novaCitiesTxt].filter(Boolean).join('. ');
      const _preTextN = applyCityAliases(normalize(_preText));
      const KNOWN_CITIES = getCities();

      const noPref = /^(sin preferencia|no preference|cualquier|any$|anywhere|flexible|sem preferência|open to any|no tengo preferencia|abierto|indifferent|cualquier destino|cualquier ciudad)$/i.test(txt.trim());

      let preferred;
      let unavNote = '';
      let _cityMatched = [];
      // Afirmación a la confirmación de destinos ya detectados → el fallback de _preText resuelve
      // Afirmación = tras quitar tokens afirmativos/cortesía no queda nada
      const AFFIRM_TOKENS = /\b(si|yes|yep|yeah|sim|claro|dale|ok|okey|okay|vale|correcto|confirmo|confirmado|confirma|confirmar|exacto|perfecto|genial|esas|esos|esa|ese|ambas|ambos|las dos|los dos|isso|por favor|porfa|please|de acuerdo|esta bien|ciudades|cidades|cities|destinos|destinations|gracias|thanks|obrigado|obrigada|sure|adelante|asi es)\b/gi;
      const _residualAff  = txtN.replace(AFFIRM_TOKENS, ' ').replace(/[\s,.!¡¿?]+/g, ' ').trim();
      const isAffirm = txt.trim().length > 0 && _residualAff === '';
      if (isAffirm && sage._nova_cities_suggest) {
        // Afirmación directa a la sugerencia guardada: fuente más fiable que re-parsear texto
        preferred = sage._nova_cities_suggest;
      } else if (isAffirm && _preText) {
        preferred = inp.messageText; // dispara el fallback de contexto inicial más abajo
      } else if (noPref) {
        preferred = LANG === 'en' ? 'Open to any destination' : LANG === 'pt' ? 'Aberto a qualquer destino' : 'Sin preferencia de destino';
      } else {
        const msgN = applyCityAliases(normalize(inp.messageText || ''));
        const seen = new Set();
        const matched = [];
        for (const city of KNOWN_CITIES) {
          if (!seen.has(city.n) && city.al.some(a => msgN.includes(normalize(a)))) {
            matched.push(city.n);
            seen.add(city.n);
          }
        }
        preferred = matched.length > 0 ? matched.join(', ') : inp.messageText;
        // Se recuerda lo que NO se reconoció para poder mencionarlo. Antes se
        // ignoraba en silencio: "Lima y Villa Fantasía" registraba Lima y el
        // paciente nunca sabía que la otra no existía.
        _cityMatched = matched;

        // Detectar fragmentos que parecen ciudades pero no están en KNOWN_CITIES
        const NOISE = /\b(tengo|interés|interes|interesa|interesado|interesada|está|estoy|bien|para|mí|ti|también|tambien|claro|cualquiera|ambas|ambos|voy|sería|seria|pueden|puede|quiero|podría|podria|me|ir|hacia|la|el|los|las|al|del|mi|sin|con|en|de|por|favor|please|gracias|ok|igual|pues|nada|más|mas|solo|solamente|sí|si|buenas|buenos|destino|destinos|ciudad|ciudades|alternativa|alternativas|opcion|opciones)\b/gi;
        const fragments = (inp.messageText || '')
          .split(/[,\/]|\s+(?:y|e|o|u|and|or)\s+/i)
          .map(s => s.replace(NOISE, ' ').replace(/\s+/g, ' ').trim())
          .filter(s => s.length >= 3);
        const unrecognized = matched.length > 0 ? [] : fragments.filter(f =>
          !KNOWN_CITIES.some(c => c.al.some(a => normalize(f).includes(normalize(a))))
        ).map(f => f.charAt(0).toUpperCase() + f.slice(1));
        // Al paciente se le SUGIEREN las ciudades del catálogo curado que
        // además tienen médicos activos (nombres reconocibles). Se ACEPTAN
        // las 36, incluidos barrios y localidades menores: si escribe
        // 'Gachala' —donde sí hay un médico— se toma como válida.
        // Sin banderas (fallback literal) se muestran todas, como antes.
        const _clean = KNOWN_CITIES.filter(c => c.hasDoctors === true && c.inCatalog === true);
        const availableList = (_clean.length > 0 ? _clean : KNOWN_CITIES).map(c => c.n).join(', ');
        // Coincidencia PARCIAL ("Lima y Villa Fantasía"): se registra Lima y se
        // menciona lo que no se reconoció, en vez de descartarlo en silencio.
        const _partial = matched.length > 0 ? fragments.filter(f =>
          !KNOWN_CITIES.some(c => c.al.some(a => normalize(f).includes(normalize(a))))
        ).map(f => f.charAt(0).toUpperCase() + f.slice(1)) : [];
        unavNote = _partial.length > 0
          ? (LANG === 'en'
            ? `\n\n_I couldn't find ${_partial.join(', ')} among our destinations, so I kept ${matched.join(', ')}._`
            : LANG === 'pt'
            ? `\n\n_Não encontrei ${_partial.join(', ')} entre nossos destinos, então mantive ${matched.join(', ')}._`
            : `\n\n_No encontré ${_partial.join(', ')} entre nuestros destinos, así que dejé ${matched.join(', ')}._`)
          : (unrecognized.length > 0
          ? (LANG === 'en'
            ? `\n\n📍 *A reminder of our current destinations:* ${availableList}.`
            : LANG === 'pt'
            ? `\n\n📍 *Lembramos nossos destinos atuais:* ${availableList}.`
            : `\n\n📍 *Le recordamos nuestros destinos actuales:* ${availableList}.`)
          : '');
        }
      // Valor previo: si esta vuelta no reconoce ninguna ciudad, se restaura.
      const _citiesBefore = sage.preferred_cities;
      sage.preferred_cities = preferred;
        // Si no se detectó ciudad del mensaje actual pero sí del contexto inicial, usarlo
      if ((!sage.preferred_cities || sage.preferred_cities === inp.messageText) && _preText) {
        const _preMatches = [];
        const _seen = new Set();
        for (const city of KNOWN_CITIES) {
          if (!_seen.has(city.n) && city.al.some(a => _preTextN.includes(normalize(a)))) {
            _preMatches.push(city.n);
            _seen.add(city.n);
          }
        }
        if (_preMatches.length > 0) {
          sage.preferred_cities = _preMatches.join(', ');
          _cityMatched = _preMatches;
        }
      }

      // ── NINGUNA CIUDAD RECONOCIDA → NO AVANZAR ────────────────
      // Antes se guardaba el mensaje crudo como destino y se seguía:
      // "Villa Fantasía" quedaba registrada como ciudad y viajaba hasta
      // el array `addresses` de Pangi, que compara cadenas literales.
      // Ahora se vuelve a preguntar conservando todo el perfil ya capturado.
      if (!noPref && _cityMatched.length === 0) {
        // No dejar el texto crudo guardado: viajaría al array `addresses` de
        // Pangi, que compara cadenas literales, y lo leería también el handoff
        // a NOVA. Se restaura lo que hubiera antes.
        if (_citiesBefore) sage.preferred_cities = _citiesBefore;
        else delete sage.preferred_cities;
        const _cl = KNOWN_CITIES.filter(c => c.hasDoctors === true && c.inCatalog === true);
        const _avail = (_cl.length > 0 ? _cl : KNOWN_CITIES).map(c => c.n).join(', ');
        sage._city_retries = (sage._city_retries || 0) + 1;
        sage.profile_step  = 'cities_pending';   // se mantiene el paso
        sage._skip_nlg_once = true;              // determinístico: Claude no debe pisarlo
        // A partir del segundo intento se ofrece una salida real:
        // 'sin preferencia' es un valor válido que publica para todos los destinos.
        const _out = sage._city_retries >= 2
          ? (LANG === 'en'
            ? `\n\n_You can also write *no preference* and doctors from any destination will see your request._`
            : LANG === 'pt'
            ? `\n\n_Você também pode escrever *sem preferência* e médicos de qualquer destino verão sua solicitação._`
            : `\n\n_También puedes escribir *sin preferencia* y los médicos de cualquier destino verán tu solicitud._`)
          : '';
        rt = LANG === 'en'
          ? `I couldn't find that city among our destinations 🔍\n\n📍 *Available destinations:* ${_avail}\n\n*Which one works for you?*${_out}`
          : LANG === 'pt'
          ? `Não encontrei essa cidade entre nossos destinos 🔍\n\n📍 *Destinos disponíveis:* ${_avail}\n\n*Qual funciona para você?*${_out}`
          : `No encontré esa ciudad entre nuestros destinos 🔍\n\n📍 *Destinos disponibles:* ${_avail}\n\n*¿Cuál te funciona?*${_out}`;
        break;
      }
      delete sage._city_retries;
      sage.profile_step = 'done';
      delete sage._nova_cities_suggest;

      const sexDisp = profile.sex === 'M'
        ? (LANG === 'en' ? 'Male' : 'Masculino')
        : (LANG === 'en' ? 'Female' : 'Femenino');
      const profSummary = LANG === 'en'
        ? `✅ *Profile:* ${profile.age}y · ${sexDisp} · ${profile.conditions || 'No conditions'} · Meds: ${profile.medications || 'None'}\n📍 *Preferred destinations:* ${sage.preferred_cities}`
        : LANG === 'pt'
        ? `✅ *Perfil:* ${profile.age}a · ${sexDisp} · ${profile.conditions || 'Sem condições'} · Meds: ${profile.medications || 'Nenhum'}\n📍 *Destinos preferidos:* ${sage.preferred_cities}`
        : `✅ *Perfil:* ${profile.age} años · ${sexDisp} · ${profile.conditions || 'Sin condiciones'} · Meds: ${profile.medications || 'Ninguno'}\n📍 *Destinos de interés:* ${sage.preferred_cities}`;

      const pendSp       = sage._prof_sp       || null;
      const pendProcKey  = sage._prof_proc_key  || null;
      const pendProcName = sage._prof_proc_name || null;
      delete sage._prof_sp; delete sage._prof_proc_key; delete sage._prof_proc_name;

      if (pendProcKey) {
        sage.specialty      = pendSp;
        sage.procedure_key  = pendProcKey;
        sage.procedure_name = pendProcName;
        sage.state          = 'procedure_confirmed';
        rt = profSummary + unavNote + '\n\n' + t('procedure_ready', {nm, procedure: pendProcName});
      } else if (pendSp) {
        sage.specialty = pendSp;
        sage.state     = 'selecting_procedure';
        const emoji    = pendSp === 'dental' ? '🦷' : '💉';
        const list     = PROCEDURES[pendSp].map((p,i) => `${i+1}. ${procName(p)}`).join('\n');
        rt = profSummary + unavNote + '\n\n' + t('procedure_prompt', {nm, emoji, list});
      } else {
        sage.state = 'selecting_specialty';
        rt = profSummary + unavNote + '\n\n' + (LANG === 'en'
          ? `Now, *which specialty do you need a quote for?*\n\n🦷 Type *1* or *dental*\n💉 Type *2* or *plastic surgery*`
          : LANG === 'pt'
          ? `Agora, *para qual especialidade você precisa de cotação?*\n\n🦷 Escreva *1* ou *dental*\n💉 Escreva *2* ou *cirurgia plástica*`
          : `Ahora, *¿para qué especialidad necesitas cotizar?*\n\n🦷 Escribe *1* o *dental*\n💉 Escribe *2* o *cirugía plástica*`);
      }
      break;
    }

    // Fallback
    rt = t('fallback', {nm});
    sage.state = 'welcome';
    break;
  }

  default: {
    rt = t('fallback', {nm});
    sage.state = 'welcome';
  }
}

return [{ json: {
  success:          true,
  responseText:     rt,
  newActiveAgent:   nag,
  newSessionState:  nss,
  newSageContext:   sage,
  inputContext:     ctx,
