// ============================================================
// PREPARAR NLG SAGE v3.0 — Multi-extracción
// ============================================================
const raw   = $input.first().json;
const motor = raw._phi_clean || raw;

const state    = motor.newSageContext?.state || '';
const sage     = motor.newSageContext || {};
const LANG     = motor.detectedLanguage || motor.userLanguage || 'es';
const userMsg  = motor.messageText ||
               $('🔍 Validar Input SAGE').first().json?.messageText || '';
const fn       = null; // PHI_STRIP
const nm       = '';

// Turno determinístico del motor (guard conversacional, cambio de destinos, handoff):
// el motor ya construyó la respuesta correcta → el NLG no debe pisarla ni alucinar.
if (sage._skip_nlg_once) {
  delete sage._skip_nlg_once;
  return [{ json: { ...raw, _nlgSkip: true, _nlgReason: 'deterministic_motor_response' } }];
}
const CLAUDE_STATES = ['questioning', 'handoff_received', 'summary', 'selecting_specialty', 'procedure_confirmed', 'gathering_profile'];
if (!CLAUDE_STATES.includes(state)) {
  return [{ json: { ...raw, _nlgSkip: true, _nlgReason: `skip_state:${state}` } }];
}

const LANG_NAMES = { es: 'español', en: 'English', pt: 'português' };
const langName = LANG_NAMES[LANG] || 'español';
const langInstruction = LANG === 'es'
  ? 'Responde SIEMPRE en español.'
  : LANG === 'en'
  ? 'Always respond in English.'
  : 'Responda SEMPRE em português.';

let systemPrompt = '';
let userContent  = '';
let maxTokens    = 400;

// ─── questioning: MULTI-EXTRACCIÓN ───────────────────────────
if (state === 'questioning') {
  const questions = sage.critical_questions || [];
  const infoKeys  = sage.required_info      || [];
  const collected = sage.collected_data     || {};
  const procedure = sage.procedure_name     || '';

  const isStartSignal = sage._qa_just_started === true;
  if (isStartSignal) {
    if (LANG === 'es') {
      return [{ json: { ...raw, _nlgSkip: true, _nlgReason: 'qa_start_signal_es' } }];
    }
    const targetLang = LANG === 'en' ? 'English' : 'Portuguese';
    return [{ json: {
      ...raw,
      _nlgSkip: false,
      _nlgState: 'procedure_confirmed',
      claudeSagePayload: {
        model: 'claude-sonnet-4-20250514',
        max_tokens: 300,
        system: `You are SAGE, a medical quotes specialist at Pangi.\nAlways respond in ${targetLang}.\n\nTranslate the following message to ${targetLang}. It may contain Spanish — translate ALL Spanish parts, especially the medical question:\n---\n${motor.responseText || ''}\n---\nKeep WhatsApp format (*bold*, emojis). Return ONLY the translated message, no explanations.`,
        messages: [{ role: 'user', content: `Translate to ${targetLang}` }]
      }
    }}];
  }

  // Augmentar formulario: si hay exámenes requeridos y aún no se preguntó → añadir al final
  const reqExams = sage.required_exams || [];
