  if (reqExams.length > 0 && !collected['exams_availability']) {
    const examsListStr = reqExams.map(e => e.replace(/_/g,' ')).join(', ');
    const examsQ = LANG === 'en'
      ? `Do you have any of these available? ${examsListStr} (photos or recent studies — you can share them here)`
      : LANG === 'pt'
      ? `Você tem disponível algum destes? ${examsListStr} (fotos ou estudos recentes — pode compartilhar aqui)`
      : `¿Tienes disponible alguno de estos? ${examsListStr} (fotos o estudios recientes — puedes compartirlos aquí)`;
    augQuestions.push(examsQ);
