  }
  // Exámenes recomendados aún no cubiertos → recordatorio opcional en el prompt
  const _exAvailN = (collected['exams_availability'] || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const _coveredPrep = Array.isArray(sage.exams_covered) ? sage.exams_covered : [];
  const pendingExams = reqExams.filter(e => {
