        glúteos_actuales:'Glúteos actuales', injerto_grasa:'Injerto de grasa',
      };
      const getLabel = k => KEY_LABELS[k] || k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());

      const summaryLines = infoKeys.map((k, i) => {
        const val = collected[k];
        if (!val) return null;
        return `✅ *${getLabel(k)}:* ${val}`;
      }).filter(Boolean).join('\n');

      const profileParts = [];
      if (patProfile.age) profileParts.push(`${patProfile.age}${LANG==='en'?'y':' años'}`);
      if (patProfile.sex) profileParts.push(patProfile.sex==='M' ? (LANG==='en'?'Male':'Masculino') : (LANG==='en'?'Female':'Femenino'));
      if (patProfile.conditions) profileParts.push(patProfile.conditions);
      if (patProfile.medications && !['Ninguno','None','Nenhum'].includes(patProfile.medications) && patProfile.medications !== patProfile.conditions) {
        profileParts.push(`Meds: ${patProfile.medications}`);
      }
      const profileLine = profileParts.length > 0
        ? `\n\n👤 *${LANG==='en'?'Patient':LANG==='pt'?'Paciente':'Paciente'}:* ${profileParts.join(' · ')}`
        : '';

      const citiesLine = cities
        ? `\n📍 *${LANG==='en'?'Preferred destinations':LANG==='pt'?'Destinos preferidos':'Destinos de interés'}:* ${cities}`
        : '';

      const fixAccents = s => s
        .replace(/\bfotografia(s)?\b/gi, 'Fotografía$1')
        .replace(/\bfotografica(s)?\b/gi, 'fotográfica$1')
        .replace(/\bmedico\b/gi, 'médico')
        .replace(/\btomografia(s)?\b/gi, 'Tomografía$1')
        .replace(/\bradiografia(s)?\b/gi, 'Radiografía$1')
        .replace(/\bpanoramica\b/gi, 'panorámica')
        .replace(/\boclusión\b/gi, 'oclusión')
        .replace(/\bexamen\b/gi, 'Examen')
        .replace(/\bclinica\b/gi, 'clínica')
        .replace(/\becografica\b/gi, 'ecográfica');
      const fmtExam = e => {
        const c = fixAccents(
          e.replace(/_/g,' ').replace(/3\s*cuartos?/gi,'3/4').replace(/3cuartos?/gi,'3/4')
        );
        return '• ' + c.charAt(0).toUpperCase() + c.slice(1);
      };
      const examsArr      = sage.required_exams || [];
      const exAvailRaw    = (collected['exams_availability']||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      const exNone        = examsNoneBonus;
      const examsRemain   = examsArr.filter(e => {
        if (_covSet.has(e)) return false; // ya recibido por adjunto
        if (exNone) return true;
        const eN  = e.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/_/g,' ');
        const key = eN.split(' ').find(w => w.length >= 4) || eN.substring(0,5);
        return !exAvailRaw.includes(key);
      });
      const examsLine = examsRemain.length > 0
        ? '\n\n📋 *' + (LANG==='en'?'Recommended exams to bring':LANG==='pt'?'Exames recomendados para trazer':'Exámenes recomendados para llevar') + ':*\n' +
          examsRemain.map(fmtExam).join('\n')
        : '';

      const scoreLabel = score >= 80
        ? (LANG==='en'?'🟢 Excellent':'🟢 Excelente')
        : score >= 60 ? (LANG==='en'?'🟡 Good':'🟡 Buena')
        : (LANG==='en'?'🔴 Basic':'🔴 Básica');

      const confirm = LANG==='en'?'*confirm*':LANG==='pt'?'*confirmar*':'*confirmar*';

      const ctaLine = score >= 100
        ? (LANG==='en' ? `Type ${confirm} to publish and start receiving quotes.`
          : LANG==='pt' ? `Escreva ${confirm} para publicar.`
          : `Escribe ${confirm} para publicar y recibir cotizaciones.`)
        : (LANG==='en' ? `You can add more information now (or send photos/exams) to strengthen your request — or type ${confirm} to publish it as is.`
          : LANG==='pt' ? `Você pode adicionar mais informações agora (ou enviar fotos/exames) — ou escreva ${confirm} para publicar como está.`
          : `Si quieres agregar más información puedes hacerlo ahora (o enviar fotos/exámenes) — o escribe ${confirm} para publicar tal como está.`);
      const summaryMsg = LANG==='en'
        ? `Done! 🎉 Your *${sage.procedure_name}* request is ready.\n\n*Case summary:*\n${summaryLines}${profileLine}${citiesLine}${examsLine}\n\n📊 *Completeness: ${score}%* — ${scoreLabel}\n\n${ctaLine}`
        : LANG==='pt'
        ? `Pronto! 🎉 Sua solicitação de *${sage.procedure_name}* está preparada.\n\n*Resumo do caso:*\n${summaryLines}${profileLine}${citiesLine}${examsLine}\n\n📊 *Completude: ${score}%* — ${scoreLabel}\n\n${ctaLine}`
        : `¡Listo! 🎉 Tu solicitud de *${sage.procedure_name}* está preparada.\n\n*Resumen de tu caso:*\n${summaryLines}${profileLine}${citiesLine}${examsLine}\n\n📊 *Completitud: ${score}%* — ${scoreLabel}\n\n${ctaLine}`;

      finalOut.responseText     = summaryMsg;
      finalOut.newSageContext   = sage;
      finalOut._nlgSource       = 'claude_nlg';
      finalOut.shouldSaveIntake = true;
      finalOut.intakePayload    = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: collected,
        missingItems: sage.required_exams || [],
        score,
        status: 'in_progress'
      }};
      return [{ json: finalOut }];
    }

    // ── Pendientes: usar responseText de Claude ───────────────
    finalOut.newSageContext   = sage;
    finalOut.shouldSaveIntake = answeredCount > 0;
    if (answeredCount > 0) {
      finalOut.intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: collected,
        missingItems: sage.required_exams || [],
        score
      }};
    }
    // FIX bucle de espera: el anuncio se evalúa sobre el MENSAJE ACTUAL (no
    // sobre el valor guardado en collected) y una pregunta del usuario SIEMPRE
    // se responde con Claude (ej: "¿cómo me tomo las fotos?").
    const _msgNowN = (finalOut.messageText || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const _announcedNow = /\b(ahora|ahorita|ya mismo|enseguida|en un momento|un momento|espera|esperame|dame un|dame \d|me la tomo|me las tomo|te la tomo|te las tomo|voy a|las adjunto|la adjunto|las envio|la envio|las mando|la mando|te la paso|te las paso|te la mando|te las mando|te la envio|te las envio|te comparto|proximamente|momentito|ya te|ahi te|alli te|will send|will take|sending|about to|hold on|give me a|momentinho|vou enviar|vou tirar|ja te envio)\b/.test(_msgNowN);
    const _userAsks = /[?¿]/.test(finalOut.messageText || '') || /\b(como|how|indicame|indica|indicas|explica|explicame|dime|de que forma)\b/.test(_msgNowN);
    if (_announcedNow && clinicalComplete && !_userAsks) {
      finalOut.responseText = LANG==='en'
        ? `Perfect! 📸 I'll wait right here for your photos/exams. Take your time — send them whenever you're ready and I'll finalize your request.`
        : LANG==='pt'
        ? `Perfeito! 📸 Fico aqui aguardando suas fotos/exames. Sem pressa — envie quando estiver pronto e eu finalizo sua solicitação.`
        : `¡Perfecto! 📸 Aquí espero tus fotos/exámenes. Tómate tu tiempo — envíalas cuando estés listo/a y finalizo tu solicitud.`;
      finalOut._nlgSource = 'deterministic_wait';
    } else if (parsed.responseText && parsed.responseText.length > 5) {
      finalOut.responseText = parsed.responseText;
      finalOut._nlgSource   = 'claude_nlg';
    } else if (_announcedSend && clinicalComplete) {
      // Fallback: Claude no devolvió texto y hay anuncio de envío guardado
      finalOut.responseText = LANG==='en'
        ? `Perfect! 📸 I'll wait right here for your photos/exams. Take your time — send them whenever you're ready and I'll finalize your request.`
        : LANG==='pt'
        ? `Perfeito! 📸 Fico aqui aguardando suas fotos/exames. Sem pressa — envie quando estiver pronto e eu finalizo sua solicitação.`
        : `¡Perfecto! 📸 Aquí espero tus fotos/exámenes. Tómate tu tiempo — envíalas cuando estés listo/a y finalizo tu solicitud.`;
      finalOut._nlgSource = 'deterministic_wait_fallback';
    }

  // ── gathering_profile: salud batch ────────────────────────
  } else if (nlgState === 'gathering_profile') {
    const LANG_P = finalOut.detectedLanguage || finalOut.userLanguage || 'es';
    const clean     = rawText.replace(/```json\n?|```\n?/g, '').trim();
    const jsonMatch = clean.match(/\{[\s\S]*\}/);
    const parsed    = JSON.parse(jsonMatch ? jsonMatch[0] : clean);

    const sage    = { ...(finalOut.newSageContext || {}) };
    const profile = { ...(finalOut.inputContext?.patientProfile || {}) };

    // Guardar campos extraídos en patientProfile
    if (parsed.age  && !isNaN(parsed.age))  profile.age  = parseInt(parsed.age);
    if (parsed.sex  && ['M','F'].includes(parsed.sex)) profile.sex = parsed.sex;
    if (parsed.conditions)  profile.conditions  = parsed.conditions;
    if (parsed.medications) profile.medications = parsed.medications;

    finalOut.inputContext = { ...(finalOut.inputContext || {}), patientProfile: profile };

    const allPresent = profile.age && profile.sex && profile.conditions && profile.medications;
    const missing = parsed.missingFields || [];

    if (!allPresent) {
      // Faltan datos → pedir solo lo que falta
      sage.profile_step = 'extracting'; // seguir extrayendo
      finalOut.newSageContext = sage;
      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    } else {
      // Todo OK → preguntar ciudades
      const sexLbl = profile.sex === 'M'
        ? (LANG_P==='en'?'Male':LANG_P==='pt'?'Masculino':'Masculino')
        : (LANG_P==='en'?'Female':LANG_P==='pt'?'Feminino':'Femenino');
      const condLbl = profile.conditions;
      const medsLbl = profile.medications;

      sage.profile_step = 'cities_pending';
      finalOut.newSageContext = sage;

      const healthAck = LANG_P === 'en'
        ? `✅ *${profile.age}y · ${sexLbl} · ${condLbl} · Meds: ${medsLbl}*`
        : LANG_P === 'pt'
        ? `✅ *${profile.age}a · ${sexLbl} · ${condLbl} · Meds: ${medsLbl}*`
        : `✅ *${profile.age} años · ${sexLbl} · ${condLbl} · Meds: ${medsLbl}*`;

      // Detectar destinos ya mencionados en el mensaje inicial (handoff)
      const _novaCtxP = finalOut.inputContext?.nova || {};
      const _novaCitiesTxt = [...(_novaCtxP.sched_cities_history || []), _novaCtxP.sched_selected_city, _novaCtxP.sched_city].filter(Boolean).join(', ');
      const _preSrc  = [sage.pendingMessage || sage._initial_context || '', _novaCitiesTxt].filter(Boolean).join('. ');
      const _preN    = _preSrc.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      // Catálogo real de Pangi. El nodo de ciudades ya se ejecutó antes en
      // la cadena. Antes había aquí una lista hardcodeada que incluía
      // 'Miami' y 'San José, CR' — que NO existen en Pangi: este nodo
      // habría confirmado destinos que el motor después rechaza.
      const _catCities = (() => {
        try {
          const r = $('🗄️ DB — Cargar Ciudades').first().json;
          if (r && r.success === true && Array.isArray(r.data) && r.data.length > 0) {
            return r.data.filter(x => x && x.city).map(x => ({
              n: x.city, hasDoctors: x.has_doctors === true, inCatalog: x.in_catalog === true
            }));
          }
        } catch (e) { /* nodo ausente → fallback */ }
        return null;
      })();
      const _norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      const _CITY_AL = _catCities
        ? _catCities.map(c => [c.n, [_norm(c.n)]])
        : [
        ['Lima',['lima']], ['Bogotá',['bogota']], ['Medellín',['medellin']], ['Cartagena',['cartagena']],
        ['Cali',['cali']], ['Ciudad de México',['cdmx','ciudad de mexico','mexico city','df']],
        ['Cancún',['cancun']], ['Monterrey',['monterrey']], ['Guadalajara',['guadalajara']],
        ['Santo Domingo',['santo domingo','dominicana']], ['Buenos Aires',['buenos aires']],
        ['Miami',['miami']], ['San José, CR',['san jose','costa rica']]
      ];
      // Ejemplos que se le muestran al paciente: del catálogo curado con
      // médicos activos. Antes decía "Miami", un destino inexistente.
      const _ex = _catCities
        ? _catCities.filter(c => c.hasDoctors && c.inCatalog).slice(0, 4).map(c => c.n).join(', ')
        : 'Medellín, Cancún, Lima, Miami';
      const _exSafe = _ex || 'Lima, Bogota, Medellín';
      const _preCities = _CITY_AL.filter(([n, als]) => als.some(a => _preN.includes(a))).map(([n]) => n);
      const _confirmQ = LANG_P === 'en'
        ? `${healthAck}\n\nI noticed you mentioned *${_preCities.join(', ')}* as destinations. *Shall I confirm those?*\n\n_Reply "yes" to confirm, or write other cities._`
        : LANG_P === 'pt'
        ? `${healthAck}\n\nVi que você mencionou *${_preCities.join(', ')}* como destinos. *Confirmo esses?*\n\n_Responda "sim" para confirmar, ou escreva outras cidades._`
        : `${healthAck}\n\nVi que mencionaste *${_preCities.join(', ')}* como destinos. *¿Los confirmo?*\n\n_Responde "sí" para confirmar, o escribe otras ciudades._`;

      const citiesQ = LANG_P === 'en'
        ? `${healthAck}\n\nNow, *which city or cities would you consider traveling to for your procedure?*\nExamples: ${_exSafe}.\n\n_Write "no preference" if open to any destination._`
        : LANG_P === 'pt'
        ? `${healthAck}\n\nAgora, *a qual cidade ou cidades você consideraria viajar?*\nEx: ${_exSafe}.\n\n_Escreva "sem preferência" se estiver aberto._`
        : `${healthAck}\n\n¿En qué *ciudad o ciudades* tienes interés realizar el procedimiento?\nEj: ${_exSafe}.\n\n_Escribe "sin preferencia" si estás abierto/a a cualquier destino._`;

      finalOut.responseText = _preCities.length > 0 ? _confirmQ : citiesQ;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── procedure_confirmed ───────────────────────────────────
  } else if (nlgState === 'procedure_confirmed') {
    if (rawText && rawText.length > 10) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── summary ───────────────────────────────────────────────
  } else if (nlgState === 'summary') {
    if (rawText.length > 20) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── handoff_received / selecting_specialty ────────────────
  } else if (nlgState === 'handoff_received' || nlgState === 'selecting_specialty') {
    const clean = rawText.replace(/```json\n?|```\n?/g, '').trim();
    try {
      const parsed = JSON.parse(clean);
      const VALID_PROC_KEYS = [
        'extraccion_simple','extraccion_muela_juicio','implante_dental','protesis_completa',
        'carillas_veneers','ortodoncia_brackets','ortodoncia_invisible','endodoncia',
        'corona_dental','limpieza_profunda','blanqueamiento','puente_dental',
        'rinoplastia','abdominoplastia','liposuccion','aumento_mamario','reduccion_mamaria',
        'bichectomia','blefaroplastia','otoplastia','lifting_facial','bbl'
      ];
      if (parsed.detectedProcedureKey &&
          VALID_PROC_KEYS.includes(parsed.detectedProcedureKey) &&
          parsed.detectedSpecialty &&
          parsed.detectedSpecialty !== 'null') {
        const sage = { ...(finalOut.newSageContext || {}) };
        sage.specialty      = parsed.detectedSpecialty;
        sage.procedure_key  = parsed.detectedProcedureKey;
        sage.procedure_name = ALL_PROC_NAMES[parsed.detectedProcedureKey] || parsed.detectedProcedureKey;
        sage.state          = 'procedure_confirmed';
        finalOut.newSageContext = sage;
      }
      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    } catch(e) {
      if (rawText.length > 10) {
        finalOut.responseText = rawText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    }

  } else {
    if (rawText.length > 10) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }
  }

} catch(e) {
  finalOut._nlgError = e.message;
  if (!finalOut.responseText) {
    const _lang = finalOut.detectedLanguage || finalOut.userLanguage || 'es';
    finalOut.responseText = _lang === 'en'
      ? 'I had a processing issue. Could you please repeat that?'
      : _lang === 'pt'
      ? 'Tive um problema de processamento. Poderia repetir?'
      : 'Tuve un problema de procesamiento. ¿Podrías repetir tu respuesta?';
  }
}

return [{ json: finalOut }];

// ============================================================
// 🔐 Strip PHI v1.0
// Elimina identificadores personales antes de llamar a Claude.
// PHI eliminado: userName, userPhone, claudeContext.userName
// Datos completos preservados en el payload principal para
// nodos downstream (WhatsApp, DB, Construir Respuesta Final).
// ============================================================
const inp = $input.first().json;

const phiClean = {
  ...inp,
  userName:  null,
  userPhone: null,
  ...(inp.claudeContext
    ? { claudeContext: { ...inp.claudeContext, userName: null } }
    : {})
};

// _phi_clean excluye también remoteJid e instance
const { remoteJid, instance, userPhone, ...clinicalOnly } = phiClean;

return [{ json: {
  ...inp,              // datos completos para nodos posteriores
  phi_stripped: true,
  _phi_clean: {
    ...clinicalOnly,   // solo datos clínicos para Claude
    userName:  null,
    userPhone: null
  }
}}];

const prepData    = $('📦 Preparar — NLG SAGE').first().json;
const claudeResp  = $input.first().json;

const sessionId    = prepData.sessionId || 'unknown';
const state        = prepData._nlgState || 'unknown';
const language     = prepData.detectedLanguage || prepData.userLanguage || 'es';
const model        = prepData.claudeSagePayload?.model || 'claude-sonnet-4-20250514';
const inputTokens  = claudeResp?.usage?.input_tokens  || 0;
const outputTokens = claudeResp?.usage?.output_tokens || 0;
const outputText   = claudeResp?.content?.[0]?.text   || '';

const PRICES = {
  'claude-sonnet-4-20250514':  { in: 3.00, out: 15.00 },
  'claude-haiku-4-5-20251001': { in: 0.80, out: 4.00  }
};
const p       = PRICES[model] || PRICES['claude-sonnet-4-20250514'];
const costUsd = ((inputTokens * p.in) + (outputTokens * p.out)) / 1_000_000;
const now     = new Date().toISOString();
const ts      = Date.now();

return [{ json: {
  _langfusePayload: {
    batch: [
      {
        id:        `trace-${sessionId}-${ts}`,
        type:      'trace-create',
        timestamp: now,
        body: {
          id:       `pangi-${sessionId}`,
          name:     `pangi-session-${sessionId}`,
          metadata: { session_id: sessionId, language, phi_stripped: prepData.phi_stripped || false }
        }
      },
      {
        id:        `sage-${sessionId}-${ts}`,
        type:      'generation-create',
        timestamp: now,
        body: {
          id:        `gen-sage-${sessionId}-${ts}`,
          traceId:   `pangi-${sessionId}`,
          name:      `sage-${state}`,
          model,
          startTime: now,
          endTime:   now,
          input:  { prompt: (prepData.claudeSagePayload?.system || '').substring(0, 800) },
          output: { text: outputText.substring(0, 500) },
          usage:  { input: inputTokens, output: outputTokens, unit: 'TOKENS' },
          metadata: {
            agent:        'SAGE',
            state,
            language,
            session_id:   sessionId,
            phi_stripped: prepData.phi_stripped || false,
            cost_usd:     parseFloat(costUsd.toFixed(6))
          }
        }
      }
    ]
  }
}}];

// Las 36 ciudades del espejo local con sus banderas. El motor SUGIERE
// las del catálogo curado que tienen médicos, pero ACEPTA cualquiera:
// si el paciente escribe 'Gachala' —donde sí hay un médico— la toma.
return [{ json: { operation: 'getCities', params: {} } }];

// Intersección entre la knowledge base y el catálogo ACTIVO de Pangi,
// ordenada por display_order. Si el CEO de Pangi apaga una especialidad o quita
// un procedimiento en el Admin, SAGE deja de ofrecerlo automáticamente.
return [{ json: { operation: 'getProcedures', params: {} } }];
